UPDATE PRJ_ANNC_BBS
SET 
	PRJ_EMP_TITLE = #{prjEmpTitle}
	, PRJ_TOPIC = #{prjTopic}
	, PRJ_START_PLAN_DATE = REPLACE(#{prjStartPlanDate}, '-', '')
	, PRJ_END_PLAN_DATE = REPLACE(#{prjEndPlanDate}, '-', '')
	, PRJ_ANNC_CONTENT = #{prjAnncContent}
	, ANNC_END_PLAN_DATE = #{anncEndPlanDate}
	, ANNC_END_YN = #{anncEndYn}
WHERE PRJ_ANNC_NO = #{prjAnncNo}
